"""Small score assembler. All timing, pitch and layers below end up as ordinary XM cells."""
import numpy as np, re, struct, math
from dataclasses import dataclass
from bank import build_bank

NBAR=40; ROWS=NBAR*16; CHANNELS=16; BPM=142

def midi(s):
    if isinstance(s,(int,np.integer)): return int(s)
    m=re.fullmatch(r'([A-G])([#b]?)(-?[0-9])',s)
    if not m: raise ValueError(s)
    return {'C':0,'D':2,'E':4,'F':5,'G':7,'A':9,'B':11}[m[1]]+{'':0,'#':1,'b':-1}[m[2]]+(int(m[3])+1)*12

def nn(m): return 'C C# D D# E F F# G G# A A# B'.split()[m%12]+str(m//12-1)

@dataclass
class Event:
    t:int
    n:int
    ins:int
    v:int
    d:float|None
    pan:int|None
    glide:float
    vibr:int
    soft:bool
    effect:tuple|None
    late:int

class Score:
    def __init__(self):
        self.bank=build_bank()
        self.events=[{} for _ in range(CHANNELS)]
        self.speeds=[]
        for b in range(NBAR):
            for r in range(16):
                sw=(not 16<=b<24) and b not in (36,37)
                if b in [3,11,15,23,27,35,39] and r>=12: sw=False
                self.speeds.append((7 if r%2==0 else 5) if sw else 6)
        self.overwrites=[]
    def put(self,ch,t,n,ins,v,d=None,pan=None,glide=0.,vibr=0,soft=False,fx=None,late=0,replace=False):
        if not(0<=t<ROWS) or not isinstance(t,int): raise ValueError(('row',t))
        if (t in self.events[ch]) and not replace:
            self.overwrites.append((ch,t,self.events[ch][t].ins,ins))
        self.events[ch][t]=Event(t,midi(n),ins,round(v),d,pan,glide,vibr,soft,fx,late)
    def compile(self,include=None, gains=None):
        c=np.zeros((ROWS,CHANNELS,5),dtype=np.uint8)
        for t,s in enumerate(self.speeds):
            if t%64==0 or self.speeds[t-1]!=s: c[t,15,3:]=15,s
        for ch,ds in enumerate(self.events):
            if include is not None and ch not in include: continue
            es=[ds[x] for x in sorted(ds)]
            for i,e in enumerate(es):
                t=e.t; nex=es[i+1] if i+1<len(es) else None; prv=es[i-1] if i>0 else None
                nt=nex.t if nex else ROWS
                if e.d is not None: dur=min(e.d,nt-t)
                else: dur=None
                # A portamento target has no new instrument/attack.
                g=bool(e.glide and prv and prv.ins==e.ins and (prv.d is None or prv.t+prv.d+0.001>=t))
                glidenext=bool(nex and nex.glide and e.ins==nex.ins and (dur is None or dur+0.001>=nt-t))
                gval=gains.get(ch,1.) if gains else 1.
                vol=np.clip(round(e.v*gval),1,64)
                ce=c[t,ch]; ce[:]=[e.n-11,e.ins if not g else 0,int(vol)+16,0,0]
                if e.pan is not None and (not g): ce[3:]=[8,e.pan]
                if e.effect: ce[3:]=e.effect
                if e.late:
                    if e.pan is not None and e.v==self.bank[e.ins-1].vol and gval==1:
                        ce[2]=0xc0+min(15,round(e.pan/17))
                    ce[3:]=[14,0xd0+e.late]
                if g:
                    s0=self.speeds[t]; sem=abs(e.n-prv.n)
                    # Number of rows the glide should occupy. Remain at the target thereafter.
                    nsteps=sum(self.speeds[j]-1 for j in range(t,min(t+max(1,int(math.ceil(e.glide))),nt)))
                    speed=int(np.clip(np.ceil(16*sem/max(nsteps,1)),1,255))
                    for j in range(t, min(t+max(1,math.ceil(e.glide)),nt)):
                        c[j,ch,3:]=[3,speed if j==t else 0]
                if dur is not None:
                    en=t+dur; k=int(math.floor(en+.0001)); frac=en-k
                    if e.vibr and dur>=2.75:
                        begin=t+(2 if dur<5.85 else 3)
                        for j in range(begin,min(math.ceil(en-0.0001),nt)):
                            if c[j,ch,3]==0 and c[j,ch,4]==0: c[j,ch,3:]=[4,e.vibr if j==begin else 0]
                    if not glidenext and e.soft and dur>=1.35:
                        # A short tick-by-tick fall at the tail instead of choking a held wave.
                        j=k if frac>=.4 else k-1
                        if t<j<nt and c[j,ch,2]==0:
                            fall=max(1,min(7,round(vol*(.62 if frac>0 else .53)/(self.speeds[j]*max(frac,.55) if frac>0 else self.speeds[j]))))
                            c[j,ch,2]=0x60+fall
                    if frac>.0001 and k<nt:
                        tick=max(1,min(self.speeds[k]-1,round(self.speeds[k]*frac)))
                        # A panned short percussion/arp note can simply ring instead.
                        if k!=t or not (e.effect or e.late or e.pan is not None or g):
                            c[k,ch,3:]=[14,0xc0+tick]
                        elif k+1<nt: c[k+1,ch,0]=97
                    elif k<nt: c[k,ch,0]=97
                    elif k==ROWS and self.bank[e.ins-1].loop and not frac and t<ROWS-1:
                        c[ROWS-1,ch,3:]=[14,0xc0+self.speeds[-1]-1]
        return c

def fixed(s,n): return s.encode('ascii','replace')[:n].ljust(n,b'\0')
def pack(fmt,*a):return struct.pack('<'+fmt,*a)

def xm(song,path,include=None,gains=None):
    cells=song.compile(include,gains); order=list(range(ROWS//64))
    n=len(order); bank=song.bank
    with open(path,'wb') as fp:
        def w(b): fp.write(b)
        w(b'Extended Module: '); w(fixed('Opal Night Line',20)); w(b'\x1a'); w(fixed('FastTracker v2.00',20)); w(pack('H',0x104));w(pack('I8H',276,n,0,CHANNELS,n,len(bank),1,6,BPM));w(bytes(order).ljust(256,b'\0'))
        for ix in order:
            data=bytearray()
            for cell in cells[ix*64:(ix+1)*64].reshape((-1,5)):
                mask=sum(1<<j for j,v in enumerate(cell) if v)
                if mask==31: data.extend(cell.tobytes())
                else:
                    data.append(128+mask);data.extend(int(v) for v in cell if v)
            w(pack('IBHH',9,0,64,len(data)));w(data)
        for a in bank:
            w(pack('I',263)); w(fixed(a.name,22)); w(pack('BHI',0,1,40));w(bytes(96+48+48+14));w(pack('H',0));w(bytes(22))
            q=round((12*np.log2(a.rate/8363.)+60-a.root+a.cents/100)*128)
            rel=(q+64)//128; fine=q-128*rel
            typ=int(bool(a.loop))+(16 if a.bits==16 else 0); b=a.bits//8
            st,ls=a.loop or (0,0)
            w(pack('IIIBbBBbB',len(a.y)*b,st*b,ls*b,a.vol,fine,typ,a.pan,rel,0));w(fixed(a.sample,22))
            arr=np.rint(a.y*(32767 if a.bits==16 else 127)).astype(np.int32)
            w(np.diff(arr,prepend=0).astype('<i2' if a.bits==16 else 'i1').tobytes())
